 85→// Load loads the Entire settings from .entire/settings.json,
 86→// then applies any overrides from .entire/settings.local.json if it exists.
 87→// Returns default settings if neither file exists.
 88→// Works correctly from any subdirectory within the repository.
 89→func Load(ctx context.Context) (*EntireSettings, error) {
 90→	// Get absolute paths for settings files
 91→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 92→	if err != nil {
 93→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 94→	}
 95→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 96→	if err != nil {
 97→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 98→	}
 99→
100→	// Load base settings
101→	settings, err := loadFromFile(settingsFileAbs)
102→	if err != nil {
103→		return nil, fmt.Errorf("reading settings file: %w", err)
104→	}
105→
106→	// Apply local overrides if they exist
107→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
108→	if err != nil {
109→		if !os.IsNotExist(err) {
110→			return nil, fmt.Errorf("reading local settings file: %w", err)
111→		}
112→		// Local file doesn't exist, continue without overrides
113→	} else {
114→		if err := mergeJSON(settings, localData); err != nil {
115→			return nil, fmt.Errorf("merging local settings: %w", err)
116→		}
117→	}
118→
119→	return settings, nil
120→}
