 66→// getGitConfigValue retrieves a git config value using the git command.
 67→// Returns empty string if the value is not set or on error.
 68→func getGitConfigValue(ctx context.Context, key string) string {
 69→	cmd := exec.CommandContext(ctx, "git", "config", "--get", key)
 70→	output, err := cmd.Output()
 71→	if err != nil {
 72→		return ""
 73→	}
 74→	return strings.TrimSpace(string(output))
 75→}
