 77→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 78→// It determines the default branch by:
 79→// 1. Checking the remote origin's HEAD reference
 80→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 81→// Returns (isDefault, branchName, error)
 82→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 83→	repo, err := openRepository(ctx)
 84→	if err != nil {
 85→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 86→	}
 87→
 88→	// Get current branch
 89→	head, err := repo.Head()
 90→	if err != nil {
 91→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 92→	}
 93→
 94→	if !head.Name().IsBranch() {
 95→		// Detached HEAD - not on any branch
 96→		return false, "", nil
 97→	}
 98→
 99→	currentBranch := head.Name().Short()
100→
101→	// Try to get default branch from remote origin's HEAD
102→	defaultBranch := getDefaultBranchFromRemote(repo)
103→
104→	// If we couldn't determine from remote, use common defaults
105→	if defaultBranch == "" {
106→		// Check if current branch is a common default name
107→		if currentBranch == "main" || currentBranch == "master" {
108→			return true, currentBranch, nil
109→		}
110→		return false, currentBranch, nil
111→	}
112→
113→	return currentBranch == defaultBranch, currentBranch, nil
114→}
