116→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
117→// Returns empty string if unable to determine.
118→func getDefaultBranchFromRemote(repo *git.Repository) string {
119→	// Try to get the symbolic reference for origin/HEAD
120→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
121→	if err == nil && ref != nil {
122→		// ref.Target() gives us something like "refs/remotes/origin/main"
123→		target := ref.Target().String()
124→		if strings.HasPrefix(target, "refs/remotes/origin/") {
125→			return strings.TrimPrefix(target, "refs/remotes/origin/")
126→		}
127→	}
128→
129→	// Fallback: check if origin/main or origin/master exists
130→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
131→		return "main"
132→	}
133→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
134→		return "master"
135→	}
136→
137→	return ""
138→}
