140→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
141→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
142→// skip the operation to avoid polluting main/master history.
143→// If the branch cannot be determined, returns (false, "") to allow the operation.
144→func ShouldSkipOnDefaultBranch(ctx context.Context) (bool, string) {
145→	isDefault, branchName, err := IsOnDefaultBranch(ctx)
146→	if err != nil {
147→		// If we can't determine, allow the operation
148→		return false, ""
149→	}
150→	return isDefault, branchName
151→}
