173→// GetMergeBase finds the common ancestor (merge-base) between two branches.
174→// Returns the hash of the merge-base commit.
175→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
176→	repo, err := openRepository(ctx)
177→	if err != nil {
178→		return nil, fmt.Errorf("failed to open git repository: %w", err)
179→	}
180→
181→	// Resolve branch references
182→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
183→	if err != nil {
184→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
185→	}
186→
187→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
188→	if err != nil {
189→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
190→	}
191→
192→	// Get commit objects
193→	commit1, err := repo.CommitObject(ref1.Hash())
194→	if err != nil {
195→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
196→	}
197→
198→	commit2, err := repo.CommitObject(ref2.Hash())
199→	if err != nil {
200→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
201→	}
202→
203→	// Find common ancestor
204→	mergeBase, err := commit1.MergeBase(commit2)
205→	if err != nil {
206→		return nil, fmt.Errorf("failed to find merge base: %w", err)
207→	}
208→
209→	if len(mergeBase) == 0 {
210→		return nil, errors.New("no common ancestor found")
211→	}
212→
213→	hash := mergeBase[0].Hash
214→	return &hash, nil
