// Package gitprovider defines interfaces for git operations and provides
// implementations backed by go-git and the git CLI. A factory selects the
// best implementation per operation category based on settings.
package gitprovider

import (
	"context"
	"time"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
)

// ReferenceProvider handles git reference (branch/tag) operations.
type ReferenceProvider interface {
	// Head returns the HEAD reference.
	Head() (*plumbing.Reference, error)

	// GetReference resolves a reference by name.
	// When resolve is true, symbolic references are dereferenced.
	GetReference(name plumbing.ReferenceName, resolve bool) (*plumbing.Reference, error)

	// SetReference creates or updates a reference.
	SetReference(ref *plumbing.Reference) error

	// ListBranches returns an iterator over all local branches.
	ListBranches() (storer.ReferenceIter, error)

	// ListReferences returns an iterator over all references.
	ListReferences() (storer.ReferenceIter, error)

	// BranchExists checks whether a local branch exists.
	BranchExists(name string) (bool, error)

	// DeleteBranch force-deletes a local branch.
	DeleteBranch(name string) error
}

// ObjectProvider handles git object (commit, tree, blob) operations.
type ObjectProvider interface {
	// CommitObject returns the commit identified by hash.
	CommitObject(hash plumbing.Hash) (*object.Commit, error)

	// TreeObject returns the tree identified by hash.
	TreeObject(hash plumbing.Hash) (*object.Tree, error)

	// BlobObject returns the blob identified by hash.
	BlobObject(hash plumbing.Hash) (*object.Blob, error)

	// Log returns a commit iterator starting from the given options.
	Log(opts *git.LogOptions) (object.CommitIter, error)

	// IsEmpty returns true when the repository has no commits.
	IsEmpty() (bool, error)

	// Storer returns the underlying object storer for low-level plumbing.
	// This is needed by the checkpoint package for in-memory tree building.
	Storer() storer.EncodedObjectStorer
}

// WorktreeProvider handles working-tree operations.
type WorktreeProvider interface {
	// Checkout switches the working tree to the given ref (branch name or commit hash).
	Checkout(ctx context.Context, ref string) error

	// HardReset resets the working tree and index to the given commit.
	HardReset(ctx context.Context, commit plumbing.Hash) error

	// HasUncommittedChanges returns true when there are staged, unstaged,
	// or untracked changes in the working tree.
	HasUncommittedChanges(ctx context.Context) (bool, error)

	// DetectFileChanges returns a detailed list of all file changes
	// (staged, unstaged, untracked) using null-separated porcelain output.
	DetectFileChanges(ctx context.Context) ([]byte, error)

	// StagedFiles returns the paths of files staged for the next commit.
	StagedFiles(ctx context.Context) ([]string, error)

	// UntrackedFiles returns paths of untracked files that are not gitignored.
	UntrackedFiles(ctx context.Context) ([]string, error)
}

// RemoteProvider handles fetch and push operations.
type RemoteProvider interface {
	// Fetch fetches a refspec from the named remote.
	// A zero timeout means no deadline.
	Fetch(ctx context.Context, remote, refSpec string, timeout time.Duration) error

	// Push pushes a refspec to the named remote.
	// When noVerify is true, pre-push hooks are skipped.
	// A zero timeout means no deadline.
	Push(ctx context.Context, remote, refSpec string, noVerify bool, timeout time.Duration) error
}

// ConfigProvider handles configuration and path-resolution operations.
type ConfigProvider interface {
	// ConfigValue returns the value for a git config key, or "" if unset.
	ConfigValue(ctx context.Context, key string) (string, error)

	// GitDir returns the .git directory path (worktree-aware).
	GitDir(ctx context.Context) (string, error)

	// GitCommonDir returns the shared .git directory (same as GitDir for
	// non-worktree repos, points to the main repo's .git for linked worktrees).
	GitCommonDir(ctx context.Context) (string, error)

	// HooksDir returns the active hooks directory, respecting core.hooksPath.
	HooksDir(ctx context.Context) (string, error)

	// WorktreeRoot returns the repository working-tree root directory.
	WorktreeRoot(ctx context.Context) (string, error)

	// ValidateBranchName checks whether a branch name is valid.
	ValidateBranchName(ctx context.Context, name string) error

	// RevParseSymbolicFullName resolves a ref to its full symbolic name
	// (e.g. "HEAD" → "refs/heads/main").
	RevParseSymbolicFullName(ctx context.Context, ref string) (string, error)
}

// DiffProvider handles diff and ancestry operations.
type DiffProvider interface {
	// DiffTree returns the list of file paths changed between two commits.
	// For initial commits (commit1 is empty), all files in commit2 are returned.
	// repoDir is the working-tree directory to run in.
	DiffTree(ctx context.Context, repoDir, commit1, commit2 string) ([]string, error)

	// IsDisconnected returns true when two commits share no common ancestor.
	IsDisconnected(ctx context.Context, hash1, hash2 string) (bool, error)
}

// Repository combines all provider sub-interfaces into a single facade.
type Repository interface {
	ReferenceProvider
	ObjectProvider
	WorktreeProvider
	RemoteProvider
	ConfigProvider
	DiffProvider
}

package gitprovider

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
)

// GoGit implements Repository using the go-git library.
// Operations that are known to be buggy in go-git v6 (Checkout, HardReset)
// or require credential helpers (Fetch, Push) return ErrNotImplemented and
// should be handled by the CLI implementation via the composite factory.
type GoGit struct {
	repo *git.Repository
}

// NewGoGit creates a go-git backed provider from an already-opened repository.
func NewGoGit(repo *git.Repository) *GoGit {
	return &GoGit{repo: repo}
}

// ErrNotImplemented is returned when an operation is not supported by a provider.
var ErrNotImplemented = errors.New("operation not implemented by this provider")

// --- ReferenceProvider ---

func (g *GoGit) Head() (*plumbing.Reference, error) {
	return g.repo.Head()
}

func (g *GoGit) GetReference(name plumbing.ReferenceName, resolve bool) (*plumbing.Reference, error) {
	return g.repo.Reference(name, resolve)
}

func (g *GoGit) SetReference(ref *plumbing.Reference) error {
	return g.repo.Storer.SetReference(ref)
}

func (g *GoGit) ListBranches() (storer.ReferenceIter, error) {
	return g.repo.Branches()
}

func (g *GoGit) ListReferences() (storer.ReferenceIter, error) {
	return g.repo.References()
}

func (g *GoGit) BranchExists(name string) (bool, error) {
	_, err := g.repo.Reference(plumbing.NewBranchReferenceName(name), true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return false, nil
		}
		return false, fmt.Errorf("checking branch %s: %w", name, err)
	}
	return true, nil
}

func (g *GoGit) DeleteBranch(name string) error {
	// go-git's branch deletion can have issues with packed refs in worktrees,
	// so this may fail in some edge cases. The CLI implementation is preferred.
	refName := plumbing.NewBranchReferenceName(name)
	return g.repo.Storer.RemoveReference(refName)
}

// --- ObjectProvider ---

func (g *GoGit) CommitObject(hash plumbing.Hash) (*object.Commit, error) {
	return g.repo.CommitObject(hash)
}

func (g *GoGit) TreeObject(hash plumbing.Hash) (*object.Tree, error) {
	return g.repo.TreeObject(hash)
}

func (g *GoGit) BlobObject(hash plumbing.Hash) (*object.Blob, error) {
	return g.repo.BlobObject(hash)
}

func (g *GoGit) Log(opts *git.LogOptions) (object.CommitIter, error) {
	return g.repo.Log(opts)
}

func (g *GoGit) IsEmpty() (bool, error) {
	_, err := g.repo.Head()
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return true, nil
		}
		return false, fmt.Errorf("checking if repository is empty: %w", err)
	}
	return false, nil
}

func (g *GoGit) Storer() storer.EncodedObjectStorer {
	return g.repo.Storer
}

// --- WorktreeProvider ---
// These return ErrNotImplemented because go-git v6 has bugs with checkout/reset
// deleting untracked directories listed in .gitignore.

func (g *GoGit) Checkout(_ context.Context, _ string) error {
	return fmt.Errorf("go-git Checkout: %w", ErrNotImplemented)
}

func (g *GoGit) HardReset(_ context.Context, _ plumbing.Hash) error {
	return fmt.Errorf("go-git HardReset: %w", ErrNotImplemented)
}

func (g *GoGit) HasUncommittedChanges(_ context.Context) (bool, error) {
	return false, fmt.Errorf("go-git HasUncommittedChanges: %w", ErrNotImplemented)
}

func (g *GoGit) DetectFileChanges(_ context.Context) ([]byte, error) {
	return nil, fmt.Errorf("go-git DetectFileChanges: %w", ErrNotImplemented)
}

func (g *GoGit) StagedFiles(_ context.Context) ([]string, error) {
	return nil, fmt.Errorf("go-git StagedFiles: %w", ErrNotImplemented)
}

func (g *GoGit) UntrackedFiles(_ context.Context) ([]string, error) {
	return nil, fmt.Errorf("go-git UntrackedFiles: %w", ErrNotImplemented)
}

// --- RemoteProvider ---
// go-git doesn't use credential helpers, so Fetch/Push return ErrNotImplemented.

func (g *GoGit) Fetch(_ context.Context, _, _ string, _ time.Duration) error {
	return fmt.Errorf("go-git Fetch: %w", ErrNotImplemented)
}

func (g *GoGit) Push(_ context.Context, _, _ string, _ bool, _ time.Duration) error {
	return fmt.Errorf("go-git Push: %w", ErrNotImplemented)
}

// --- ConfigProvider ---

func (g *GoGit) ConfigValue(_ context.Context, _ string) (string, error) {
	return "", fmt.Errorf("go-git ConfigValue: %w", ErrNotImplemented)
}

func (g *GoGit) GitDir(_ context.Context) (string, error) {
	return "", fmt.Errorf("go-git GitDir: %w", ErrNotImplemented)
}

func (g *GoGit) GitCommonDir(_ context.Context) (string, error) {
	return "", fmt.Errorf("go-git GitCommonDir: %w", ErrNotImplemented)
}

func (g *GoGit) HooksDir(_ context.Context) (string, error) {
	return "", fmt.Errorf("go-git HooksDir: %w", ErrNotImplemented)
}

func (g *GoGit) WorktreeRoot(_ context.Context) (string, error) {
	return "", fmt.Errorf("go-git WorktreeRoot: %w", ErrNotImplemented)
}

func (g *GoGit) ValidateBranchName(_ context.Context, _ string) error {
	return fmt.Errorf("go-git ValidateBranchName: %w", ErrNotImplemented)
}

func (g *GoGit) RevParseSymbolicFullName(_ context.Context, _ string) (string, error) {
	return "", fmt.Errorf("go-git RevParseSymbolicFullName: %w", ErrNotImplemented)
}

// --- DiffProvider ---

func (g *GoGit) DiffTree(_ context.Context, _, _, _ string) ([]string, error) {
	return nil, fmt.Errorf("go-git DiffTree: %w", ErrNotImplemented)
}

func (g *GoGit) IsDisconnected(_ context.Context, _, _ string) (bool, error) {
