package gitprovider

// Compile-time interface satisfaction checks.
var (
	_ Repository = (*GoGit)(nil)
	_ Repository = (*CLI)(nil)
	_ Repository = (*Composite)(nil)
)

//nolint:wrapcheck // GoGit is a thin delegation layer over go-git; wrapping would add noise without value.
package gitprovider

import (
	"errors"
	"fmt"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
	"github.com/go-git/go-git/v6/storage"
)

// GoGit implements ReferenceProvider and ObjectProvider using the go-git library.
type GoGit struct {
	repo *git.Repository
}

// NewGoGit creates a go-git backed provider from an already-opened repository.
func NewGoGit(repo *git.Repository) *GoGit {
	return &GoGit{repo: repo}
}

// --- ReferenceProvider ---

func (g *GoGit) Head() (*plumbing.Reference, error) {
	return g.repo.Head()
}

func (g *GoGit) GetReference(name plumbing.ReferenceName, resolve bool) (*plumbing.Reference, error) {
	return g.repo.Reference(name, resolve)
}

func (g *GoGit) SetReference(ref *plumbing.Reference) error {
	return g.repo.Storer.SetReference(ref)
}

func (g *GoGit) ListBranches() (storer.ReferenceIter, error) {
	return g.repo.Branches()
}

func (g *GoGit) ListReferences() (storer.ReferenceIter, error) {
	return g.repo.References()
}

func (g *GoGit) BranchExists(name string) (bool, error) {
	_, err := g.repo.Reference(plumbing.NewBranchReferenceName(name), true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return false, nil
		}
		return false, fmt.Errorf("checking branch %s: %w", name, err)
	}
	return true, nil
}

func (g *GoGit) DeleteBranch(name string) error {
	refName := plumbing.NewBranchReferenceName(name)
	return g.repo.Storer.RemoveReference(refName)
}

// --- ObjectProvider ---

func (g *GoGit) CommitObject(hash plumbing.Hash) (*object.Commit, error) {
	return g.repo.CommitObject(hash)
}

func (g *GoGit) TreeObject(hash plumbing.Hash) (*object.Tree, error) {
	return g.repo.TreeObject(hash)
}

func (g *GoGit) BlobObject(hash plumbing.Hash) (*object.Blob, error) {
	return g.repo.BlobObject(hash)
}

func (g *GoGit) Log(opts *git.LogOptions) (object.CommitIter, error) {
	return g.repo.Log(opts)
}

func (g *GoGit) IsEmpty() (bool, error) {
	_, err := g.repo.Head()
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return true, nil
		}
		return false, fmt.Errorf("checking if repository is empty: %w", err)
	}
	return false, nil
}

func (g *GoGit) Storer() storage.Storer {
	return g.repo.Storer
}

package gitprovider

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
)

// CLI implements WorktreeProvider, RemoteProvider, ConfigProvider, DiffProvider,
// and the branch-related subset of ReferenceProvider by shelling out to the git binary.
type CLI struct {
	// dir is the working directory for git commands.
	// Empty string means use the process's current directory.
	dir string
}

// NewCLI creates a CLI-backed provider that runs git commands in dir.
// If dir is empty, the current working directory is used.
func NewCLI(dir string) *CLI {
	return &CLI{dir: dir}
}

// run executes a git command and returns its trimmed stdout.
func (c *CLI) run(ctx context.Context, args ...string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", args...)
	if c.dir != "" {
		cmd.Dir = c.dir
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("git %s: %s: %w", args[0], strings.TrimSpace(stderr.String()), err)
	}
	return strings.TrimSpace(stdout.String()), nil
}

// runRaw executes a git command and returns raw stdout bytes (no trimming).
func (c *CLI) runRaw(ctx context.Context, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, "git", args...)
	if c.dir != "" {
		cmd.Dir = c.dir
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("git %s: %s: %w", args[0], strings.TrimSpace(stderr.String()), err)
	}
	return stdout.Bytes(), nil
}

// --- ReferenceProvider (branch subset) ---

func (c *CLI) BranchExists(name string) (bool, error) {
	ctx := context.Background()
	_, err := c.run(ctx, "show-ref", "--verify", "--quiet", "refs/heads/"+name)
	if err != nil {
		// show-ref exits 1 when the ref doesn't exist
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

func (c *CLI) DeleteBranch(name string) error {
	ctx := context.Background()

	exists, err := c.BranchExists(name)
	if err != nil {
		return err
	}
	if !exists {
		return fmt.Errorf("branch %q does not exist", name)
	}

	_, err = c.run(ctx, "branch", "-D", "--", name)
	return err
}

// --- WorktreeProvider ---

func (c *CLI) Checkout(ctx context.Context, ref string) error {
	if strings.HasPrefix(ref, "-") {
		return fmt.Errorf("checkout failed: invalid ref %q", ref)
	}
	_, err := c.run(ctx, "checkout", ref)
	return err
}

func (c *CLI) HardReset(ctx context.Context, commit plumbing.Hash) error {
	_, err := c.run(ctx, "reset", "--hard", commit.String())
	return err
}

func (c *CLI) HasUncommittedChanges(ctx context.Context) (bool, error) {
	output, err := c.run(ctx, "status", "--porcelain")
	if err != nil {
		return false, err
	}
	return len(output) > 0, nil
}

func (c *CLI) DetectFileChanges(ctx context.Context) ([]byte, error) {
	return c.runRaw(ctx, "status", "--porcelain", "-z", "-uall")
}

func (c *CLI) StagedFiles(ctx context.Context) ([]string, error) {
	output, err := c.run(ctx, "diff", "--cached", "--name-only")
	if err != nil {
		return nil, err
	}
	if output == "" {
		return nil, nil
	}
	return strings.Split(output, "\n"), nil
}

func (c *CLI) UntrackedFiles(ctx context.Context) ([]string, error) {
	raw, err := c.runRaw(ctx, "ls-files", "--others", "--exclude-standard", "-z")
	if err != nil {
		return nil, err
	}
	if len(raw) == 0 {
		return nil, nil
	}
	parts := bytes.Split(raw, []byte{0})
	var files []string
	for _, p := range parts {
		if len(p) > 0 {
			files = append(files, string(p))
		}
	}
	return files, nil
}

// --- RemoteProvider ---

func (c *CLI) Fetch(ctx context.Context, remote, refSpec string, timeout time.Duration) error {
	if timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, timeout)
		defer cancel()
	}

	_, err := c.run(ctx, "fetch", remote, refSpec)
	if err != nil && ctx.Err() == context.DeadlineExceeded {
		return fmt.Errorf("fetch timed out after %s", timeout)
	}
	return err
}

func (c *CLI) Push(ctx context.Context, remote, refSpec string, noVerify bool, timeout time.Duration) error {
	if timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, timeout)
		defer cancel()
	}

	args := []string{"push"}
	if noVerify {
		args = append(args, "--no-verify")
	}
	args = append(args, remote, refSpec)

	_, err := c.run(ctx, args...)
	if err != nil && ctx.Err() == context.DeadlineExceeded {
		return fmt.Errorf("push timed out after %s", timeout)
	}
	return err
}

// --- ConfigProvider ---

func (c *CLI) ConfigValue(ctx context.Context, key string) (string, error) {
	output, err := c.run(ctx, "config", "--get", key)
	if err != nil {
		// git config --get exits 1 when the key is not set
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return "", nil
		}
		return "", err
	}
	return output, nil
}

func (c *CLI) GitDir(ctx context.Context) (string, error) {
	output, err := c.run(ctx, "rev-parse", "--git-dir")
	if err != nil {
		return "", errors.New("not a git repository")
	}
	return c.makeAbs(output), nil
}

func (c *CLI) GitCommonDir(ctx context.Context) (string, error) {
	output, err := c.run(ctx, "rev-parse", "--git-common-dir")
	if err != nil {
		return "", errors.New("not a git repository")
	}
	return c.makeAbs(output), nil
}

func (c *CLI) HooksDir(ctx context.Context) (string, error) {
	output, err := c.run(ctx, "rev-parse", "--git-path", "hooks")
	if err != nil {
		return "", errors.New("not a git repository")
	}
	return c.makeAbs(output), nil
}

func (c *CLI) WorktreeRoot(ctx context.Context) (string, error) {
	return c.run(ctx, "rev-parse", "--show-toplevel")
}

func (c *CLI) ValidateBranchName(ctx context.Context, name string) error {
	_, err := c.run(ctx, "check-ref-format", "--branch", name)
	if err != nil {
		return fmt.Errorf("invalid branch name %q", name)
	}
	return nil
}

func (c *CLI) RevParseSymbolicFullName(ctx context.Context, ref string) (string, error) {
	return c.run(ctx, "rev-parse", "--symbolic-full-name", ref)
}

// --- DiffProvider ---

func (c *CLI) DiffTree(ctx context.Context, repoDir, commit1, commit2 string) ([]string, error) {
	var args []string
	if commit1 == "" {
		args = []string{"diff-tree", "--root", "--no-commit-id", "-r", "-z", commit2}
	} else {
		args = []string{"diff-tree", "--no-commit-id", "-r", "-z", commit1, commit2}
	}

	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = repoDir

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("git diff-tree: %s: %w", strings.TrimSpace(stderr.String()), err)
	}

	return parseDiffTreeOutput(stdout.Bytes()), nil
}

func (c *CLI) IsDisconnected(ctx context.Context, hash1, hash2 string) (bool, error) {
	_, err := c.run(ctx, "merge-base", hash1, hash2)
	if err != nil {
		// merge-base exits 1 when there is no common ancestor
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return true, nil
		}
		return false, err
	}
	return false, nil
}

// makeAbs converts a potentially relative path to absolute using the CLI's dir.
func (c *CLI) makeAbs(path string) string {
	if filepath.IsAbs(path) {
		return filepath.Clean(path)
	}
	base := c.dir
	if base == "" {
		base = "."
	}
	return filepath.Clean(filepath.Join(base, path))
}

// parseDiffTreeOutput parses null-separated git diff-tree -r -z output.
func parseDiffTreeOutput(data []byte) []string {
	if len(data) == 0 {
		return nil
	}

	parts := bytes.Split(data, []byte{0})
	var files []string
	i := 0
	for i < len(parts) {
		part := string(parts[i])
		if strings.HasPrefix(part, ":") {
			status := extractDiffStatus(part)
			i++
			if i >= len(parts) {
				break
			}
			if path := string(parts[i]); path != "" {
				files = append(files, path)
			}
			i++
			// Renames (R) and copies (C) have a second path
			if (status == 'R' || status == 'C') && i < len(parts) {
				if path2 := string(parts[i]); path2 != "" && !strings.HasPrefix(path2, ":") {
					files = append(files, path2)
					i++
				}
			}
		} else {
			i++
		}
	}
	return files
}

// extractDiffStatus extracts the single-char status from a diff-tree status line.
func extractDiffStatus(statusLine string) byte {
	fields := strings.Fields(strings.TrimSpace(statusLine))
	if len(fields) < 5 || len(fields[4]) == 0 {
		return 0
	}
	return fields[4][0]
}

package gitprovider

// Compile-time interface satisfaction checks.
var (
	// GoGit implements reference and object operations.
	_ ReferenceProvider = (*GoGit)(nil)
	_ ObjectProvider    = (*GoGit)(nil)

	// CLI implements worktree, remote, config, and diff operations.
	_ WorktreeProvider = (*CLI)(nil)
	_ RemoteProvider   = (*CLI)(nil)
	_ ConfigProvider   = (*CLI)(nil)
	_ DiffProvider     = (*CLI)(nil)

	// Composite implements the full Repository interface.
	_ Repository = (*Composite)(nil)
)

package gitprovider

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6"
)

// ProviderName identifies a git provider implementation.
type ProviderName string

const (
	// ProviderGoGit selects the go-git library implementation.
	ProviderGoGit ProviderName = "go-git"
	// ProviderCLI selects the git CLI implementation.
	ProviderCLI ProviderName = "cli"
)

// CategoryConfig maps each provider category to an implementation name.
// Any zero-value entry falls back to the category default.
type CategoryConfig struct {
	References ProviderName `json:"references,omitempty"`
	Objects    ProviderName `json:"objects,omitempty"`
	Worktree   ProviderName `json:"worktree,omitempty"`
	Remote     ProviderName `json:"remote,omitempty"`
	Config     ProviderName `json:"config,omitempty"`
	Diff       ProviderName `json:"diff,omitempty"`
}

// DefaultConfig returns the recommended defaults:
//   - go-git for references and objects (fast, in-process)
//   - CLI for worktree, remote, config, diff (correct, uses credential helpers)
func DefaultConfig() CategoryConfig {
	return CategoryConfig{
		References: ProviderGoGit,
		Objects:    ProviderGoGit,
		Worktree:   ProviderCLI,
		Remote:     ProviderCLI,
		Config:     ProviderCLI,
		Diff:       ProviderCLI,
	}
}

// Open creates a Repository using the given category configuration.
// It opens a go-git repository if any category requires it, and creates
// a CLI provider for categories that need it.
func Open(ctx context.Context, cfg CategoryConfig) (Repository, error) {
	cfg = withDefaults(cfg)

	needsGoGit := cfg.References == ProviderGoGit ||
		cfg.Objects == ProviderGoGit

	var goGitProvider *GoGit
	var cliProvider *CLI

	if needsGoGit {
		repo, err := openGoGitRepo(ctx)
		if err != nil {
			return nil, fmt.Errorf("opening go-git repository: %w", err)
		}
		goGitProvider = NewGoGit(repo)
	}

	// CLI is always available as fallback.
	cliProvider = NewCLI("")

	refs, err := pickRef(cfg.References, goGitProvider, cliProvider)
	if err != nil {
		return nil, err
	}

	objs, err := pickObj(cfg.Objects, goGitProvider, cliProvider)
	if err != nil {
		return nil, err
	}

	return NewComposite(
		WithReferenceProvider(refs),
		WithObjectProvider(objs),
		WithWorktreeProvider(cliProvider),
		WithRemoteProvider(cliProvider),
		WithConfigProvider(cliProvider),
		WithDiffProvider(cliProvider),
	), nil
}

// OpenDefault creates a Repository using defaults merged with any
// git_provider overrides from .entire/settings.json.
func OpenDefault(ctx context.Context) (Repository, error) {
	return Open(ctx, ConfigFromSettings(ctx))
}

// ConfigFromSettings reads the git_provider section from the Entire settings
// and converts it to a CategoryConfig. Missing fields use sensible defaults.
func ConfigFromSettings(ctx context.Context) CategoryConfig {
	cfg := DefaultConfig()

	s, err := settings.Load(ctx)
	if err != nil || s.GitProvider == nil {
		return cfg
	}

	gp := s.GitProvider
	if p := toProviderName(gp.References); p != "" {
		cfg.References = p
	}
	if p := toProviderName(gp.Objects); p != "" {
		cfg.Objects = p
	}
	if p := toProviderName(gp.Worktree); p != "" {
		cfg.Worktree = p
	}
	if p := toProviderName(gp.Remote); p != "" {
		cfg.Remote = p
	}
	if p := toProviderName(gp.Config); p != "" {
		cfg.Config = p
	}
	if p := toProviderName(gp.Diff); p != "" {
		cfg.Diff = p
	}
	return cfg
}

// toProviderName converts a settings string to a ProviderName.
// Returns "" for unrecognized values, which the caller treats as "use default".
func toProviderName(s string) ProviderName {
	switch s {
	case string(ProviderGoGit):
		return ProviderGoGit
	case string(ProviderCLI):
		return ProviderCLI
	default:
		return ""
	}
}

// openGoGitRepo opens a go-git repository from the worktree root.
func openGoGitRepo(ctx context.Context) (*git.Repository, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "."
	}
	repo, err := git.PlainOpen(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("failed to open repository at %s: %w", repoRoot, err)
	}
	return repo, nil
}

// withDefaults fills in zero-value fields with sensible defaults.
func withDefaults(cfg CategoryConfig) CategoryConfig {
	defaults := DefaultConfig()
	if cfg.References == "" {
		cfg.References = defaults.References
	}
	if cfg.Objects == "" {
		cfg.Objects = defaults.Objects
	}
	if cfg.Worktree == "" {
		cfg.Worktree = defaults.Worktree
	}
	if cfg.Remote == "" {
		cfg.Remote = defaults.Remote
	}
	if cfg.Config == "" {
		cfg.Config = defaults.Config
	}
	if cfg.Diff == "" {
		cfg.Diff = defaults.Diff
	}
	return cfg
}

func pickRef(name ProviderName, goGit *GoGit, _ *CLI) (ReferenceProvider, error) {
	if name == ProviderGoGit {
		if goGit == nil {
			return nil, fmt.Errorf("go-git provider required for references but not available")
		}
		return goGit, nil
	}
	return nil, fmt.Errorf("CLI provider does not support full ReferenceProvider (only BranchExists/DeleteBranch)")
}

func pickObj(name ProviderName, goGit *GoGit, _ *CLI) (ObjectProvider, error) {
	if name == ProviderGoGit {
		if goGit == nil {
			return nil, fmt.Errorf("go-git provider required for objects but not available")
		}
		return goGit, nil
	}
	return nil, fmt.Errorf("CLI provider does not support ObjectProvider")
}

