221→// getMetadataTree returns the metadata branch tree, trying local first,
222→// then fetching from remote, then falling back to the remote tree directly.
223→func getMetadataTree(ctx context.Context, repo *git.Repository) (*object.Tree, error) {
224→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
225→	if err == nil {
226→		return metadataTree, nil
227→	}
228→
229→	// Try fetching from remote
230→	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
231→		metadataTree, err = strategy.GetMetadataBranchTree(repo)
232→		if err == nil {
233→			return metadataTree, nil
234→		}
235→	}
236→
237→	// Try remote tree directly
238→	remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
239→	if remoteErr != nil {
240→		return nil, fmt.Errorf("metadata branch not available: %w", remoteErr)
241→	}
242→	return remoteTree, nil
243→}
