 66→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 67→// It determines the default branch by:
 68→// 1. Checking the remote origin's HEAD reference
 69→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 70→// Returns (isDefault, branchName, error)
 71→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 72→	repo, err := openProvider(ctx)
 73→	if err != nil {
 74→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 75→	}
 76→
 77→	// Get current branch
 78→	head, err := repo.Head()
 79→	if err != nil {
 80→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 81→	}
 82→
 83→	if !head.Name().IsBranch() {
 84→		// Detached HEAD - not on any branch
 85→		return false, "", nil
 86→	}
 87→
 88→	currentBranch := head.Name().Short()
 89→
 90→	// Try to get default branch from remote origin's HEAD
 91→	defaultBranch := getDefaultBranchFromRemote(repo)
 92→
 93→	// If we couldn't determine from remote, use common defaults
 94→	if defaultBranch == "" {
 95→		// Check if current branch is a common default name
 96→		if currentBranch == "main" || currentBranch == "master" {
 97→			return true, currentBranch, nil
 98→		}
 99→		return false, currentBranch, nil
100→	}
101→
102→	return currentBranch == defaultBranch, currentBranch, nil
103→}
