105→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
106→// Returns empty string if unable to determine.
107→func getDefaultBranchFromRemote(repo gitprovider.Repository) string {
108→	// Try to get the symbolic reference for origin/HEAD
109→	ref, err := repo.GetReference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
110→	if err == nil && ref != nil {
111→		// ref.Target() gives us something like "refs/remotes/origin/main"
112→		target := ref.Target().String()
113→		if strings.HasPrefix(target, "refs/remotes/origin/") {
114→			return strings.TrimPrefix(target, "refs/remotes/origin/")
115→		}
116→	}
117→
118→	// Fallback: check if origin/main or origin/master exists
119→	if _, err := repo.GetReference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
120→		return "main"
121→	}
122→	if _, err := repo.GetReference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
123→		return "master"
124→	}
125→
126→	return ""
127→}
