162→// GetMergeBase finds the common ancestor (merge-base) between two branches.
163→// Returns the hash of the merge-base commit.
164→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
165→	repo, err := openProvider(ctx)
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to open git repository: %w", err)
168→	}
169→
170→	// Resolve branch references
171→	ref1, err := repo.GetReference(plumbing.NewBranchReferenceName(branch1), true)
172→	if err != nil {
173→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
174→	}
175→
176→	ref2, err := repo.GetReference(plumbing.NewBranchReferenceName(branch2), true)
177→	if err != nil {
178→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
179→	}
180→
181→	// Get commit objects
182→	commit1, err := repo.CommitObject(ref1.Hash())
183→	if err != nil {
184→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
185→	}
186→
187→	commit2, err := repo.CommitObject(ref2.Hash())
188→	if err != nil {
189→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
190→	}
191→
192→	// Find common ancestor
193→	mergeBase, err := commit1.MergeBase(commit2)
194→	if err != nil {
195→		return nil, fmt.Errorf("failed to find merge base: %w", err)
196→	}
197→
198→	if len(mergeBase) == 0 {
199→		return nil, errors.New("no common ancestor found")
200→	}
201→
202→	hash := mergeBase[0].Hash
203→	return &hash, nil
204→}
